"""Additional bounded method comparisons drawn only from reviewed corpus rows."""
from final_common import *
A=rows('mission-3/assumptions/reviewed.jsonl')+rows('mission-3/assumptions/reviewed-review-and-fees.jsonl')
T=sum([rows('mission-3/extractions/'+p) for p in ['12-portfolio-task-coverage.jsonl','08-operational-curated-activities.jsonl','09-other-curated-activities.jsonl']],[])
base=[x for x in rows('analysis/adjudicated-comparisons.jsonl') if int(x['id'][4:])<=18]
