def assum(ref,family):return next(x for x in A if x['ref']==ref and x['family']==family)
def task(ref,label):return next(x for x in T if x['ref']==ref and x['activity']==label)
def add(n,title,family,members,why,diff,test,result,classification,strength='strong',extra=None):
    ps=[];obs=[]
    for x in members:
        p=x['provenance'];ps.append(p)
        v=x.get('normalized_value',x.get('minutes_per_response'));u=x.get('unit') if 'normalized_value' in x else 'minutes/source_defined_task'
        obs.append(dict(id=ident('CMPOBS',n,x['id']),ref=x['ref'],activity=x.get('activity',x.get('scope')),source_record_id=x['id'],original_value=x.get('original_value',v),original_unit=x.get('original_unit',u),normalized_value=v,unit=u,period=x.get('period'),period_unknown_reason=x.get('unknown_reason','Event or stock boundary specified in scope; no annual total inferred.'),epistemic_status='NORMALIZED',provenance=[p]))
    if extra:ps+=extra
    r=dict(id=f'CMP-{n:02}',finding_id=f'CMP-{n:02}',comparison_group=f'GRP-{n:02}',title=title,family=family,level='cross_ICR_or_lineage',refs=sorted({x['ref'] for x in members}),observations=obs,original_values=[x['original_value'] for x in obs],normalized_values=[x['normalized_value'] for x in obs],units=[x['unit'] for x in obs],similarity=dict(strength=strength,rationale=why,observable_matches=why,unknowns='Underlying empirical timing samples and unreported implementation choices are not assumed equal.'),difference_observed=diff,material_differences=diff,candidate_explanation_tested=test,evidence_assessed=result,classification=classification,confidence=dict(level='high' if strength=='strong' else 'moderate',basis='Confidence in bounded public-evidence conclusion.'),practitioner_significance=dict(priority='review' if classification=='UNRESOLVED' else 'reusable_method',reason='Preserve event, actor and lifecycle boundaries when reusing time or cost assumptions.'),epistemic_status='INFERRED',provenance=ps,limitations='Only listed versions/components. Equality does not establish empirical accuracy; serial versions are not independent replications.',causal_boundary='No inference about internal offices, staff procedures or intent.',adversarial_challenge=dict(alternative=test,result=result,retained_classification=classification))
    base.append(r);G.append(dict(id=r['comparison_group'],family=family,title=title,members=[x['id'] for x in obs],refs=r['refs'],rationale=why,similarity=r['similarity'],inclusion_rule='Listed source-defined components only.',exclusions=test,numeric_comparison_allowed=classification not in ['NOT_COMPARABLE','UNRESOLVED'],provenance=ps))
add(19,'Maryland Three familiarization across renewal','familiarization',[assum(r,'familiarization') for r in ['202112-1652-002','202501-1652-002']],'Same pilot application step: read directions and familiarize with process; per applicant.','0.5 hour in each version.','Separate familiarization from travel and the complete 5.75-hour bundle.','Separate row in both tables retains the same step and duration; wage changes do not change this time coefficient.','CONSISTENT')
add(20,'Proposed COIP legal review across submissions','legal_review',[assum(r,'legal_review') for r in ['202403-1652-002','202409-1652-001']],'Same proposed COIP Federal legal review row in two submissions.','4 hours per legal review in each.','Check actor and proposal status; do not count as two implemented programs.','Identical Federal legal-review component; 50% eligibility is a separate coefficient. These are proposed versions, not evidence of implemented workload.','CONSISTENT')
add(21,'Coordinator turnover models have different denominators','turnover',[assum('202606-1652-001','turnover'),assum('202504-1652-005','turnover')],'Both model recurring coordinator contact changes; person-stock fraction and operator-event count remain distinct.','4% annual substitution versus one operator update/year.','Can denominator, turnover universe and coordinator/alternate cardinality be aligned?','No aligned pipeline person-stock denominator or shared empirical calibration is established. Do not form a numeric ratio; retain method-selection question.','UNRESOLVED','moderate')
add(22,'mDL initial and insufficient-application resubmission','application',[task('202409-1652-003',l) for l in ['mDL initial waiver application','mDL insufficient-application resubmission']],'Same State waiver process, different lifecycle steps explicitly identified.','20 hours initial and 5 hours resubmission.','Does a resubmission replace or add to initial work?','Source defines resubmission as incremental 25% of initial effort; not a mutually exclusive initial path.','DIFFERENT_EXPLAINED')
add(23,'Annual recordkeeping is not per-record entry','recordkeeping',[task('202402-1652-001','Flight school recordkeeping'),assum('202304-1652-002','recordkeeping')],'Recordkeeping label is shared; school annual bundle and individual training-record event are different units.','104 hours per school/year versus 1 minute per training record.','Test frequency, annual bundle and event denominator.','No common per-record denominator for the annual school bundle. Reject numerical comparison.','NOT_COMPARABLE','weak')
add(24,'TRIP form time revised using user experience','appeal',[task(r,'TRIP redress form') for r in ['202502-1652-003','202511-1652-001']],'Same traveler redress application across successive versions.','60 minutes becomes 30 minutes.','Inspect Item15 for task removal, collection mode or timing evidence.','Current Item15 attributes the reduction to user experience. Underlying timing sample remains unavailable; this supports explanation, not measured universal completion time.','DIFFERENT_EXPLAINED',extra=evidence('202511-1652-001',[145]))
add(25,'SSI bidder CHRC pathway includes additional activities','threat_assessment',[task('202411-1652-008',l) for l in ['SSI bidder submission without CHRC','SSI bidder submission with CHRC']],'Same bidder eligibility context; conditional fingerprint/travel tasks differ.','15 minutes without CHRC versus 116 minutes with CHRC.','Test whether both durations cover the same bundle.','With-CHRC pathway includes fingerprinting and travel/wait omitted from the no-CHRC pathway. Scope explains the different total durations.','DIFFERENT_EXPLAINED')
add(26,'LEOSA rejection review request across renewals','appeal',[task(r,'LEOSA rejection review request') for r in ['202203-1652-006','202507-1652-001']],'Same rejected applicant preparing a review request; separate from routine application.','8 hours in each version.','Do not compare appeal preparation with the five-minute initial form.','Source-defined review-request component persists across versions.','CONSISTENT')
add(27,'Pipeline physical incident reporting across renewals','notification',[task(r,'Pipeline physical security incident report') for r in ['202109-1652-008','202504-1652-005']],'Same corporate security manager collects, reviews and submits physical-security incident report; stated maximum time.','30-minute maximum in each.','Distinguish maximum from mean; exclude cybersecurity contact updates.','Same task boundary and maximum statistic recur. This is not a finding that actual mean time is 30 minutes.','CONSISTENT')
add(28,'Federal processing versus eligibility verification','federal_review_time',[assum('202411-1652-006','federal_review_time'),assum('202411-1652-001','federal_review_time')],'Federal application handling is shared only at a broad label level.','3-minute FFDO electronic processing versus 45-minute LEO eligibility determination.','Test legal requirement, actor workflow, verification scope and source evidence.','Eligibility determination explicitly verifies application information; matching the substantive verification scope to FFDO processing is unsupported. Reject label-only ratio.','NOT_COMPARABLE','weak')
